import { useOrders } from "../../context/OrderContext";

export default function UserOrders() {
  const { orders } = useOrders();

  return (
    <div className="fade">
      <h3>Your Orders</h3>
      {orders.map(o => (
        <div key={o.id} className="card">
          <span className={`badge ${o.status.toLowerCase()}`}>
            {o.status}
          </span>
        </div>
      ))}
    </div>
  );
}
